import unittest
from candidate import max_element


class TestMaxElement(unittest.TestCase):
    def test_max_element_positive_integers(self):
        self.assertEqual(max_element([1, 2, 3]), 3)

    def test_max_element_mixed_positive_negative(self):
        self.assertEqual(max_element([5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10]), 123)

    def test_max_element_all_negative(self):
        self.assertEqual(max_element([-5, -2, -8, -1, -9]), -1)

    def test_max_element_single_element(self):
        self.assertEqual(max_element([42]), 42)

    def test_max_element_all_same_elements(self):
        self.assertEqual(max_element([7, 7, 7, 7]), 7)

    def test_max_element_with_floats(self):
        self.assertEqual(max_element([1.5, 2.3, 0.7, 3.14]), 3.14)

    def test_max_element_mixed_int_and_float(self):
        self.assertEqual(max_element([1, 2.5, 3, 2.9]), 3)

    def test_max_element_with_zero(self):
        self.assertEqual(max_element([0, -1, -2, 3]), 3)

    def test_max_element_all_zeros(self):
        self.assertEqual(max_element([0, 0, 0]), 0)

    def test_max_element_two_elements(self):
        self.assertEqual(max_element([1, 2]), 2)
        self.assertEqual(max_element([2, 1]), 2)

    def test_max_element_large_numbers(self):
        self.assertEqual(max_element([1000000, 2000000, 500000]), 2000000)

    def test_max_element_negative_large_numbers(self):
        self.assertEqual(max_element([-1000000, -2000000, -500000]), -500000)

    def test_max_element_boolean_values(self):
        self.assertEqual(max_element([False, True, False]), True)

    def test_max_element_string_list(self):
        self.assertEqual(max_element(["apple", "banana", "cherry"]), "cherry")

    def test_max_element_empty_list_raises_index_error(self):
        with self.assertRaises(IndexError):
            max_element([])

    def test_max_element_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            max_element(None)

    def test_max_element_list_with_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            max_element([1, None, 3])

    def test_max_element_list_with_incompatible_types_raises_type_error(self):
        with self.assertRaises(TypeError):
            max_element([1, "two", 3])

    def test_max_element_non_list_input_string(self):
        with self.assertRaises(TypeError):
            max_element("hello")

    def test_max_element_non_list_input_integer(self):
        with self.assertRaises(TypeError):
            max_element(5)

    def test_max_element_max_at_beginning(self):
        self.assertEqual(max_element([10, 1, 2, 3, 4]), 10)

    def test_max_element_max_at_end(self):
        self.assertEqual(max_element([1, 2, 3, 4, 10]), 10)

    def test_max_element_max_in_middle(self):
        self.assertEqual(max_element([1, 10, 2, 3, 4]), 10)

    def test_max_element_duplicate_max_values(self):
        self.assertEqual(max_element([5, 3, 5, 2, 5]), 5)

    def test_max_element_negative_and_positive(self):
        self.assertEqual(max_element([-100, -50, 0, 50, 100]), 100)

    def test_max_element_single_negative(self):
        self.assertEqual(max_element([-1]), -1)

    def test_max_element_single_zero(self):
        self.assertEqual(max_element([0]), 0)

    def test_max_element_very_small_floats(self):
        self.assertEqual(max_element([1e-10, 1e-5, 1e-2]), 1e-2)

    def test_max_element_very_large_floats(self):
        self.assertEqual(max_element([1e10, 1e15, 1e12]), 1e15)


if __name__ == '__main__':
    unittest.main()
